let (tx, rx) = crossbeam_channel::bounded::<Job>(100);
let workers: Vec<_> = (0..n).map(|_| {
    let rx = rx.clone();
    std::thread::spawn(move || {
        while let Ok(job) = rx.recv() {   // MPMC: one worker per message
            process(job);
        }
    })
}).collect();
for j in jobs { tx.send(j).unwrap(); }
drop(tx);
for w in workers { w.join().unwrap(); }

