let (tx, rx) = async_channel::bounded::<Job>(100);
for _ in 0..n {
    let rx = rx.clone();
    tokio::spawn(async move {
        while let Ok(job) = rx.recv().await {   // each job to exactly one task
            process(job).await;
        }
    });
}
